#!/usr/bin/env node
/**
 * MCP Server Connectivity Test for @juspay/shelly
 *
 * Tests connectivity to configured MCP servers.
 * Validates that servers are accessible and responding.
 *
 * @generated 2026-02-08
 * @owner juspay
 *
 * Usage:
 *   node scripts/mcp-test.cjs              # Test all enabled servers
 *   node scripts/mcp-test.cjs github       # Test specific server
 *   node scripts/mcp-test.cjs --all        # Test all servers (even disabled)
 */

const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

// ============================================================================
// CONFIGURATION
// ============================================================================

const MCP_CONFIG_PATHS = [
  '.mcp-servers.json',
  '.mcp-servers.local.json',
  path.join(process.env.HOME || '', '.config', 'mcp', 'servers.json'),
];

const TIMEOUT = 10000; // 10 seconds

// ============================================================================
// HELPERS
// ============================================================================

const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  dim: '\x1b[2m',
};

function log(message, type = 'info') {
  const prefix = {
    error: `${colors.red}✖${colors.reset}`,
    warn: `${colors.yellow}⚠${colors.reset}`,
    success: `${colors.green}✔${colors.reset}`,
    info: `${colors.blue}ℹ${colors.reset}`,
    pending: `${colors.yellow}○${colors.reset}`,
  };
  console.log(`${prefix[type] || prefix.info} ${message}`);
}

/**
 * Load MCP configuration.
 */
function loadConfig() {
  for (const configPath of MCP_CONFIG_PATHS) {
    if (fs.existsSync(configPath)) {
      try {
        const content = fs.readFileSync(configPath, 'utf-8');
        // Remove comments
        const jsonContent = content.replace(/\/\*[\s\S]*?\*\/|\/\/.*/g, '');
        const config = JSON.parse(jsonContent);
        log(`Loaded config from: ${configPath}`, 'info');
        return config;
      } catch (error) {
        log(`Failed to parse ${configPath}: ${error.message}`, 'error');
      }
    }
  }

  log('No MCP configuration found', 'warn');
  log('Expected locations:', 'info');
  MCP_CONFIG_PATHS.forEach((p) => console.log(`   - ${p}`));

  return null;
}

/**
 * Substitute environment variables in config values.
 */
function substituteEnvVars(value) {
  if (typeof value !== 'string') return value;

  return value.replace(/\{\{(\w+)\}\}/g, (match, envVar) => {
    return process.env[envVar] || match;
  });
}

/**
 * Test an MCP server connection.
 */
function testServer(name, serverConfig) {
  return new Promise((resolve) => {
    const { command, args = [], env = {} } = serverConfig;

    // Substitute environment variables
    const processedArgs = args.map(substituteEnvVars);
    const processedEnv = {};
    for (const [key, value] of Object.entries(env)) {
      processedEnv[key] = substituteEnvVars(value);
    }

    log(`Testing ${name}...`, 'pending');

    // Check if command exists (use 'where' on Windows, 'which' on Unix-like systems)
    const commandFinder = process.platform === 'win32' ? 'where' : 'which';
    const which = spawn(commandFinder, [command], { shell: true });

    which.on('close', (code) => {
      if (code !== 0) {
        resolve({
          name,
          success: false,
          error: `Command not found: ${command}`,
        });
        return;
      }

      // Try to spawn the server briefly
      const serverProcess = spawn(command, processedArgs, {
        env: { ...process.env, ...processedEnv },
        stdio: ['pipe', 'pipe', 'pipe'],
        shell: true,
      });

      let stdout = '';
      let stderr = '';

      serverProcess.stdout.on('data', (data) => {
        stdout += data.toString();
      });

      serverProcess.stderr.on('data', (data) => {
        stderr += data.toString();
      });

      // Set timeout
      const timeout = setTimeout(() => {
        // If process is still running after timeout, it's likely working
        serverProcess.kill('SIGTERM');
        resolve({
          name,
          success: true,
          message: 'Server started successfully',
        });
      }, TIMEOUT);

      serverProcess.on('close', (code) => {
        clearTimeout(timeout);

        if (code === 0 || code === null) {
          resolve({
            name,
            success: true,
            message: 'Server responded OK',
          });
        } else {
          resolve({
            name,
            success: false,
            error: stderr || `Exit code: ${code}`,
          });
        }
      });

      serverProcess.on('error', (error) => {
        clearTimeout(timeout);
        resolve({
          name,
          success: false,
          error: error.message,
        });
      });
    });
  });
}

/**
 * Check required environment variables for a server.
 */
function checkEnvVars(name, serverConfig) {
  const missing = [];
  const env = serverConfig.env || {};

  for (const [key, value] of Object.entries(env)) {
    // Check if value references an environment variable
    const match = value.match(/\{\{(\w+)\}\}/);
    if (match && !process.env[match[1]]) {
      missing.push(match[1]);
    }
  }

  return missing;
}

// ============================================================================
// MAIN
// ============================================================================

async function main() {
  const args = process.argv.slice(2);
  const testAll = args.includes('--all') || args.includes('-a');
  const specificServer = args.find((a) => !a.startsWith('-'));

  console.log('\n🔌 MCP Server Connectivity Test\n');

  // Load configuration
  const config = loadConfig();
  if (!config || !config.mcpServers) {
    process.exit(1);
  }

  const servers = config.mcpServers;
  const serverNames = Object.keys(servers).filter(
    (name) => !name.startsWith('_') // Skip metadata keys
  );

  // Filter servers
  let toTest = serverNames;

  if (specificServer) {
    if (!servers[specificServer]) {
      log(`Server not found: ${specificServer}`, 'error');
      log(`Available servers: ${serverNames.join(', ')}`, 'info');
      process.exit(1);
    }
    toTest = [specificServer];
  } else if (!testAll) {
    toTest = serverNames.filter((name) => servers[name].enabled !== false);
  }

  if (toTest.length === 0) {
    log('No servers to test', 'warn');
    log('Use --all to test disabled servers', 'info');
    process.exit(0);
  }

  console.log(`Testing ${toTest.length} server(s)...\n`);

  // Test each server
  const results = [];

  for (const name of toTest) {
    const serverConfig = servers[name];

    // Check environment variables first
    const missingEnv = checkEnvVars(name, serverConfig);
    if (missingEnv.length > 0) {
      results.push({
        name,
        success: false,
        error: `Missing env vars: ${missingEnv.join(', ')}`,
        skipped: true,
      });
      continue;
    }

    const result = await testServer(name, serverConfig);
    results.push(result);
  }

  // Print results
  console.log('\n📊 Results:\n');

  const successful = results.filter((r) => r.success);
  const failed = results.filter((r) => !r.success && !r.skipped);
  const skipped = results.filter((r) => r.skipped);

  if (successful.length > 0) {
    console.log(
      `${colors.green}Successful (${successful.length}):${colors.reset}`
    );
    successful.forEach((r) => log(`${r.name}: ${r.message}`, 'success'));
    console.log('');
  }

  if (skipped.length > 0) {
    console.log(`${colors.yellow}Skipped (${skipped.length}):${colors.reset}`);
    skipped.forEach((r) => log(`${r.name}: ${r.error}`, 'warn'));
    console.log('');
  }

  if (failed.length > 0) {
    console.log(`${colors.red}Failed (${failed.length}):${colors.reset}`);
    failed.forEach((r) => log(`${r.name}: ${r.error}`, 'error'));
    console.log('');
  }

  // Summary
  console.log('─'.repeat(40));
  console.log(
    `Total: ${results.length} | ` +
      `${colors.green}Pass: ${successful.length}${colors.reset} | ` +
      `${colors.yellow}Skip: ${skipped.length}${colors.reset} | ` +
      `${colors.red}Fail: ${failed.length}${colors.reset}`
  );
  console.log('');

  process.exit(failed.length > 0 ? 1 : 0);
}

main().catch((error) => {
  log(`Fatal error: ${error.message}`, 'error');
  process.exit(1);
});

#!/usr/bin/env node
/**
 * MCP Server Connectivity Test for {{projectName}}
 *
 * Tests connectivity to configured MCP servers.
 * Validates that servers are accessible and responding.
 *
 * @generated {{date}}
 * @owner {{owner}}
 *
 * Usage:
 *   node scripts/mcp-test.cjs              # Test all enabled servers
 *   node scripts/mcp-test.cjs github       # Test specific server
 *   node scripts/mcp-test.cjs --all        # Test all servers (even disabled)
 */

const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

// ============================================================================
// CONFIGURATION
// ============================================================================

const MCP_CONFIG_PATHS = [
  '.mcp-servers.json',
  '.mcp-servers.local.json',
  path.join(process.env.HOME || '', '.config', 'mcp', 'servers.json'),
];

const TIMEOUT = 10000; // 10 seconds

// ============================================================================
// HELPERS
// ============================================================================

const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  dim: '\x1b[2m',
};

function log(message, type = 'info') {
  const prefix = {
    error: `${colors.red}✖${colors.reset}`,
    warn: `${colors.yellow}⚠${colors.reset}`,
    success: `${colors.green}✔${colors.reset}`,
    info: `${colors.blue}ℹ${colors.reset}`,
    pending: `${colors.yellow}○${colors.reset}`,
  };
  console.log(`${prefix[type] || prefix.info} ${message}`);
}

/**
 * Load MCP configuration.
 */
function loadConfig() {
  for (const configPath of MCP_CONFIG_PATHS) {
    if (fs.existsSync(configPath)) {
      try {
        const content = fs.readFileSync(configPath, 'utf-8');
        // Remove comments
        const jsonContent = content.replace(/\/\*[\s\S]*?\*\/|\/\/.*/g, '');
        const config = JSON.parse(jsonContent);
        log(`Loaded config from: ${configPath}`, 'info');
        return config;
      } catch (error) {
        log(`Failed to parse ${configPath}: ${error.message}`, 'error');
      }
    }
  }

  log('No MCP configuration found', 'warn');
  log('Expected locations:', 'info');
  MCP_CONFIG_PATHS.forEach((p) => console.log(`   - ${p}`));

  return null;
}

/**
 * Substitute environment variables in config values.
 */
function substituteEnvVars(value) {
  if (typeof value !== 'string') return value;

  return value.replace(/\{\{(\w+)\}\}/g, (match, envVar) => {
    return process.env[envVar] || match;
  });
}

/**
 * Test an MCP server connection.
 */
function testServer(name, serverConfig) {
  return new Promise((resolve) => {
    const { command, args = [], env = {} } = serverConfig;

    // Substitute environment variables
    const processedArgs = args.map(substituteEnvVars);
    const processedEnv = {};
    for (const [key, value] of Object.entries(env)) {
      processedEnv[key] = substituteEnvVars(value);
    }

    log(`Testing ${name}...`, 'pending');

    // Check if command exists (use 'where' on Windows, 'which' on Unix-like systems)
    const commandFinder = process.platform === 'win32' ? 'where' : 'which';
    const which = spawn(commandFinder, [command], { shell: true });

    which.on('close', (code) => {
      if (code !== 0) {
        resolve({
          name,
          success: false,
          error: `Command not found: ${command}`,
        });
        return;
      }

      // Try to spawn the server briefly
      const serverProcess = spawn(command, processedArgs, {
        env: { ...process.env, ...processedEnv },
        stdio: ['pipe', 'pipe', 'pipe'],
        shell: true,
      });

      let stdout = '';
      let stderr = '';

      serverProcess.stdout.on('data', (data) => {
        stdout += data.toString();
      });

      serverProcess.stderr.on('data', (data) => {
        stderr += data.toString();
      });

      // Set timeout
      const timeout = setTimeout(() => {
        // If process is still running after timeout, it's likely working
        serverProcess.kill('SIGTERM');
        resolve({
          name,
          success: true,
          message: 'Server started successfully',
        });
      }, TIMEOUT);

      serverProcess.on('close', (code) => {
        clearTimeout(timeout);

        if (code === 0 || code === null) {
          resolve({
            name,
            success: true,
            message: 'Server responded OK',
          });
        } else {
          resolve({
            name,
            success: false,
            error: stderr || `Exit code: ${code}`,
          });
        }
      });

      serverProcess.on('error', (error) => {
        clearTimeout(timeout);
        resolve({
          name,
          success: false,
          error: error.message,
        });
      });
    });
  });
}

/**
 * Check required environment variables for a server.
 */
function checkEnvVars(name, serverConfig) {
  const missing = [];
  const env = serverConfig.env || {};

  for (const [key, value] of Object.entries(env)) {
    // Check if value references an environment variable
    const match = value.match(/\{\{(\w+)\}\}/);
    if (match && !process.env[match[1]]) {
      missing.push(match[1]);
    }
  }

  return missing;
}

// ============================================================================
// MAIN
// ============================================================================

async function main() {
  const args = process.argv.slice(2);
  const testAll = args.includes('--all') || args.includes('-a');
  const specificServer = args.find((a) => !a.startsWith('-'));

  console.log('\n🔌 MCP Server Connectivity Test\n');

  // Load configuration
  const config = loadConfig();
  if (!config || !config.mcpServers) {
    process.exit(1);
  }

  const servers = config.mcpServers;
  const serverNames = Object.keys(servers).filter(
    (name) => !name.startsWith('_') // Skip metadata keys
  );

  // Filter servers
  let toTest = serverNames;

  if (specificServer) {
    if (!servers[specificServer]) {
      log(`Server not found: ${specificServer}`, 'error');
      log(`Available servers: ${serverNames.join(', ')}`, 'info');
      process.exit(1);
    }
    toTest = [specificServer];
  } else if (!testAll) {
    toTest = serverNames.filter((name) => servers[name].enabled !== false);
  }

  if (toTest.length === 0) {
    log('No servers to test', 'warn');
    log('Use --all to test disabled servers', 'info');
    process.exit(0);
  }

  console.log(`Testing ${toTest.length} server(s)...\n`);

  // Test each server
  const results = [];

  for (const name of toTest) {
    const serverConfig = servers[name];

    // Check environment variables first
    const missingEnv = checkEnvVars(name, serverConfig);
    if (missingEnv.length > 0) {
      results.push({
        name,
        success: false,
        error: `Missing env vars: ${missingEnv.join(', ')}`,
        skipped: true,
      });
      continue;
    }

    const result = await testServer(name, serverConfig);
    results.push(result);
  }

  // Print results
  console.log('\n📊 Results:\n');

  const successful = results.filter((r) => r.success);
  const failed = results.filter((r) => !r.success && !r.skipped);
  const skipped = results.filter((r) => r.skipped);

  if (successful.length > 0) {
    console.log(`${colors.green}Successful (${successful.length}):${colors.reset}`);
    successful.forEach((r) => log(`${r.name}: ${r.message}`, 'success'));
    console.log('');
  }

  if (skipped.length > 0) {
    console.log(`${colors.yellow}Skipped (${skipped.length}):${colors.reset}`);
    skipped.forEach((r) => log(`${r.name}: ${r.error}`, 'warn'));
    console.log('');
  }

  if (failed.length > 0) {
    console.log(`${colors.red}Failed (${failed.length}):${colors.reset}`);
    failed.forEach((r) => log(`${r.name}: ${r.error}`, 'error'));
    console.log('');
  }

  // Summary
  console.log('─'.repeat(40));
  console.log(
    `Total: ${results.length} | ` +
      `${colors.green}Pass: ${successful.length}${colors.reset} | ` +
      `${colors.yellow}Skip: ${skipped.length}${colors.reset} | ` +
      `${colors.red}Fail: ${failed.length}${colors.reset}`
  );
  console.log('');

  process.exit(failed.length > 0 ? 1 : 0);
}

main().catch((error) => {
  log(`Fatal error: ${error.message}`, 'error');
  process.exit(1);
});

name: Shelly Copilot Review

on:
  pull_request:
    types: [opened, synchronize, reopened]
    paths:
      - 'src/**/*.js'
      - 'test/**/*.js'
      - 'scripts/**/*.js'
      - '*.js'
      - '*.md'

permissions:
  contents: read
  pull-requests: write
  issues: write

env:
  FORCE_COLOR: 1

jobs:
  copilot-review:
    name: AI Code Review
    runs-on: ubuntu-latest

    steps:
      - name: 📥 Checkout code
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: 🔧 Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20.x'
          cache: 'npm'

      - name: 📦 Install dependencies
        run: npm install

      - name: 🧪 Run Tests
        run: npm test
        continue-on-error: true

      - name: 🔍 Lint Code
        run: npm run lint
        continue-on-error: true

      - name: 🔍 Shelly-specific Review Summary
        uses: actions/github-script@v7
        if: github.event_name == 'pull_request' && github.event.pull_request.head.repo.full_name == github.repository
        with:
          script: |
            const { data: files } = await github.rest.pulls.listFiles({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            // Categorize changed files by Shelly feature area
            const categories = {
              'error-analysis': [],
              'repository-organization': [],
              'memory-bank': [],
              'ai-integration': [],
              'shell-integration': [],
              'cli-interface': [],
              'documentation': [],
              'other': []
            };

            files.forEach(file => {
              const path = file.filename;
              if (path.includes('src/main.js') || path.includes('analysisService') || path.includes('historyService')) {
                categories['error-analysis'].push(path);
              } else if (path.includes('organize') || path.includes('templates') || path.includes('github')) {
                categories['repository-organization'].push(path);
              } else if (path.includes('memory') || path.includes('Memory') || path.includes('memory-bank')) {
                categories['memory-bank'].push(path);
              } else if (path.includes('ai') || path.includes('neurolink') || path.includes('aiContentGenerator')) {
                categories['ai-integration'].push(path);
              } else if (path.includes('shell') || path.includes('Shell')) {
                categories['shell-integration'].push(path);
              } else if (path.includes('cli.js') || path.includes('commands/')) {
                categories['cli-interface'].push(path);
              } else if (path.endsWith('.md') || path.includes('docs/')) {
                categories['documentation'].push(path);
              } else {
                categories['other'].push(path);
              }
            });

            let summary = '🤖 **Shelly AI Code Review Completed**\n\n';
            summary += '### 📋 Changed Files by Feature Area:\n\n';

            Object.entries(categories).forEach(([category, files]) => {
              if (files.length > 0) {
                const emoji = {
                  'error-analysis': '🔍',
                  'repository-organization': '🏗️', 
                  'memory-bank': '🧠',
                  'ai-integration': '🤖',
                  'shell-integration': '🐚',
                  'cli-interface': '🔧',
                  'documentation': '📚',
                  'other': '📄'
                }[category] || '📄';

                summary += `${emoji} **${category.replace('-', ' ').toUpperCase()}** (${files.length} files)\n`;
                files.forEach(file => summary += `   - \`${file}\`\n`);
                summary += '\n';
              }
            });

            summary += '### 🔍 Review Focus Areas:\n';
            summary += '- **Error Analysis**: Command parsing, AI suggestion accuracy, shell compatibility\n';
            summary += '- **Repository Organization**: Project scaffolding, GitHub integration, file operations\n';
            summary += '- **Memory Bank**: AI context management, documentation generation, persistence\n';
            summary += '- **Security**: Shell injection prevention, file system safety, input validation\n';
            summary += '- **Performance**: Memory usage, response times, resource management\n';
            summary += '- **Cross-Platform**: macOS/Linux compatibility, shell-specific features\n\n';
            summary += '📝 Check the **Files Changed** tab for detailed AI feedback on each file.\n';
            summary += '🚀 Ensure all Shelly features (Error Analysis, Repository Organization, Memory Bank) work seamlessly together!';

            github.rest.issues.createComment({
              issue_number: context.issue.number,
              owner: context.repo.owner,
              repo: context.repo.repo,
              body: summary
            });

#!/usr/bin/env node
/**
 * Fixes node-pty spawn-helper permissions after installation.
 *
 * This script addresses an issue where pnpm (and sometimes npm) doesn't preserve
 * executable permissions on native binaries. The spawn-helper binary in node-pty
 * needs to be executable, otherwise posix_spawnp fails on macOS/Linux.
 */

import { chmod, access, constants } from 'fs/promises';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';
import { platform, arch } from 'os';

const __dirname = dirname(fileURLToPath(import.meta.url));

async function fixPermissions() {
  // Skip on Windows - not affected by this issue
  if (platform() === 'win32') {
    return;
  }

  const currentPlatform = platform();
  const currentArch = arch();
  const prebuildDir = `${currentPlatform}-${currentArch}`;

  // Possible locations where node-pty might be installed
  const possiblePaths = [
    // pnpm with different versions
    resolve(
      __dirname,
      '../node_modules/.pnpm/node-pty@0.10.1/node_modules/node-pty/prebuilds',
      prebuildDir,
      'spawn-helper'
    ),
    resolve(
      __dirname,
      '../node_modules/.pnpm/node-pty@1.1.0/node_modules/node-pty/prebuilds',
      prebuildDir,
      'spawn-helper'
    ),
    // npm/yarn standard location
    resolve(
      __dirname,
      '../node_modules/node-pty/prebuilds',
      prebuildDir,
      'spawn-helper'
    ),
    // pnpm hoisted
    resolve(
      __dirname,
      '../../node_modules/node-pty/prebuilds',
      prebuildDir,
      'spawn-helper'
    ),
  ];

  for (const helperPath of possiblePaths) {
    try {
      // Check if file exists
      await access(helperPath, constants.F_OK);

      // Check if already executable
      try {
        await access(helperPath, constants.X_OK);
        console.log(
          `[fix-node-pty] spawn-helper already executable: ${helperPath}`
        );
        return;
      } catch {
        // Not executable, fix it
        await chmod(helperPath, 0o755);
        console.log(
          `[fix-node-pty] Fixed spawn-helper permissions: ${helperPath}`
        );
        return;
      }
    } catch {
      // File doesn't exist at this path, try next
      continue;
    }
  }

  // If we get here, we couldn't find spawn-helper - this might be okay
  // (e.g., running on a platform without prebuilds)
  console.log(
    `[fix-node-pty] spawn-helper not found for ${prebuildDir} - this may be expected`
  );
}

fixPermissions().catch((err) => {
  console.error('[fix-node-pty] Error fixing permissions:', err.message);
  // Don't fail the install - the user might not need node-pty functionality
  process.exit(0);
});

/**
 * Setup Tier Configuration
 * Defines the three-tier system for repository scaffolding complexity.
 * File-level tier assignments live in utils/fileTiers.ts (single source of truth).
 * This file owns: directory lists and feature flags per tier.
 */

export type SetupTier = 'essential' | 'standard' | 'complete';

export interface TierConfig {
  directories: string[];
  includeMemoryBank: boolean;
  includeBreezeMcp: boolean;
  includeChangeset: boolean;
}

const ESSENTIAL_CONFIG: TierConfig = {
  directories: [
    'src',
    'tests',
    'test',
    'docs',
    'examples',
    '.github',
    '.github/ISSUE_TEMPLATE',
    '.github/workflows',
    '.husky',
  ],
  includeMemoryBank: false,
  includeBreezeMcp: false,
  includeChangeset: false,
};

const STANDARD_CONFIG: TierConfig = {
  directories: [
    ...ESSENTIAL_CONFIG.directories,
    'config',
    'scripts',
    'tools',
    'todos',
    '.husky',
    'scripts/git-hooks',
    '.github/ISSUE_TEMPLATE',
    '.github/workflows',
    'src/commands',
    'src/providers',
    'src/services',
    'tools/automation',
    'tools/testing',
    'tools/development',
    'tools/content',
  ],
  includeMemoryBank: false,
  includeBreezeMcp: false,
  includeChangeset: false,
};

const COMPLETE_CONFIG: TierConfig = {
  directories: [
    ...STANDARD_CONFIG.directories,
    '.ai/workflows',
    '.claude/commands',
    'memory-bank',
    'memory-bank/project',
    'memory-bank/technical',
    'memory-bank/current',
    '.changeset',
    'tools/automation',
    'tools/testing',
    'tools/development',
    'tools/content',
  ],
  includeMemoryBank: true,
  includeBreezeMcp: true,
  includeChangeset: true,
};

export const SETUP_TIERS: Record<SetupTier, TierConfig> = {
  essential: ESSENTIAL_CONFIG,
  standard: STANDARD_CONFIG,
  complete: COMPLETE_CONFIG,
};

export function getTierConfig(tier: SetupTier): TierConfig {
  return SETUP_TIERS[tier];
}

export function isValidTier(value: string): value is SetupTier {
  return ['essential', 'standard', 'complete'].includes(value);
}

export function getTierDisplayName(tier: SetupTier): string {
  const names: Record<SetupTier, string> = {
    essential: 'Essential',
    standard: 'Standard',
    complete: 'Complete',
  };
  return names[tier];
}

export function getTierDescription(tier: SetupTier): string {
  const descriptions: Record<SetupTier, string> = {
    essential:
      '📦 Essential - Basic setup (~20 files) - Quick start, small projects',
    standard:
      '🚀 Standard - Production-ready (~50 files) - Team projects, best practices',
    complete:
      '💎 Complete - Enterprise + AI (~100+ files) - Full features, AI integration',
  };
  return descriptions[tier];
}

export function getTierFileCount(tier: SetupTier): string {
  const counts: Record<SetupTier, string> = {
    essential: '~20',
    standard: '~50',
    complete: '~100+',
  };
  return counts[tier];
}
